//-- 1. กำหนด Topic ที่ระบบ PlantCare ยอมรับ
const topics = {
    'plantcare/ait/plant01/esp32_01/soil': 0,
    'plantcare/ait/plant01/esp32_01/thermal': 1,
    'plantcare/ait/plant01/esp32_01/status': 2
};

//-- 2. เตรียม Output จำนวน 4 ช่อง: Soil, Thermal, Status, Error
const outputs = [null, null, null, null];

//-- 3. ฟังก์ชันรายงานข้อผิดพลาด
function reject(reason) {
    node.warn('PlantCare validation: ' + reason);
    outputs[3] = {
        topic: msg.topic,
        payload: { error: reason, data_source: 'simulated' }
    };
    return outputs;
}

//-- 4. ตรวจ Topic เพื่อไม่ให้ข้อมูลจาก Lab อื่นปะปน
if (!Object.prototype.hasOwnProperty.call(topics, msg.topic)) {
    return reject('Unknown PlantCare topic');
}

//-- 5. ตรวจรูปแบบ JSON Object
const p = msg.payload;
if (p === null || typeof p !== 'object' || Array.isArray(p)) {
    return reject('Payload must be a JSON object');
}

//-- 6. ตรวจชื่ออุปกรณ์และแหล่งที่มาของข้อมูล
if (p.plant_id !== 'plant01' || p.device_id !== 'esp32_01') {
    return reject('Unexpected plant_id or device_id');
}
if (p.data_source !== 'simulated' && p.data_source !== 'real') {
    return reject('Invalid data_source');
}

//-- 7. ตรวจค่า Soil ให้เป็นตัวเลขที่สมเหตุสมผล
if (msg.topic.endsWith('/soil')) {
    if (!Number.isFinite(p.soil_adc_raw) || p.soil_adc_raw < 0 || p.soil_adc_raw > 4095 || !Number.isFinite(p.relative_wetness_pct) || p.relative_wetness_pct < 0 || p.relative_wetness_pct > 100) {
        return reject('Invalid Soil ADC or Wetness Index');
    }
}

//-- 8. ตรวจ Thermal Summary ว่ามีตัวเลขครบ
if (msg.topic.endsWith('/thermal')) {
    for (const field of ['t_left_c', 't_right_c', 't_max_c', 'delta_t_c']) {
        if (!Number.isFinite(p[field])) {
            return reject('Invalid Thermal field: ' + field);
        }
    }
}

//-- 9. ตรวจสถานะ Sensor
if (msg.topic.endsWith('/status')) {
    if (typeof p.soil_sensor_ok !== 'boolean' || typeof p.thermal_sensor_ok !== 'boolean') {
        return reject('Invalid sensor status flags');
    }
}

//-- 10. เพิ่มเวลารับข้อมูลที่ Node-RED
// สำหรับ Inject Test ใช้เวลาปัจจุบันเป็นเวลาของตัวอย่าง
// ข้อมูลจาก ESP32 จริงควรมีเวลาวัดจากอุปกรณ์แยกต่างหาก
const now = new Date().toISOString();
msg.payload = {
    ...p,
    schema_version: 2,
    timestamp: p.timestamp || now,
    received_at: now
};

//-- 11. ส่งไปยัง Debug ตามประเภทของข้อมูล
outputs[topics[msg.topic]] = msg;
return outputs;

const expectedKey = env.get("PLANTCARE_INGEST_KEY");
const suppliedKey = msg.req?.headers?.["x-plantcare-key"];

function respond(status, body, soil = null, thermal = null) {
    msg.statusCode = status;
    msg.headers = {
        "Content-Type": "application/json",
        "Cache-Control": "no-store"
    };
    msg.payload = body;
    return [msg, soil, thermal];
}

// 1. ตรวจ API Key ก่อนอ่านข้อมูล
if (
    typeof expectedKey !== "string" ||
    expectedKey.length < 32 ||
    typeof suppliedKey !== "string" ||
    suppliedKey !== expectedKey
) {
    return respond(401, {
        ok: false,
        error: "invalid_api_key"
    });
}

// 2. ตรวจ JSON Body
let data;

try {
    data = typeof msg.payload === "string"
        ? JSON.parse(msg.payload)
        : msg.payload;
} catch (error) {
    return respond(400, {
        ok: false,
        error: "invalid_json"
    });
}

if (!data || typeof data !== "object" || Array.isArray(data)) {
    return respond(400, {
        ok: false,
        error: "invalid_payload"
    });
}

// 3. ตรวจ Device Metadata
if (
    data.plant_id !== "plant01" ||
    data.device_id !== "esp32_01" ||
    !["simulated", "real"].includes(data.data_source)
) {
    return respond(400, {
        ok: false,
        error: "invalid_metadata"
    });
}

const tags = {
    plant_id: data.plant_id,
    device_id: data.device_id,
    data_source: data.data_source
};

const validNumber = (x) =>
    typeof x === "number" && Number.isFinite(x);

let soilMsg = null;
let thermalMsg = null;

// 4. เตรียมข้อมูล Soil
if (data.soil !== undefined && data.soil !== null) {
    const s = data.soil;

    if (
        typeof s !== "object" ||
        s.sensor_ok !== true ||
        !validNumber(s.raw) ||
        !validNumber(s.filtered_raw) ||
        !validNumber(s.relative_wetness_pct) ||
        s.raw < 0 || s.raw > 4095 ||
        s.filtered_raw < 0 || s.filtered_raw > 4095 ||
        s.relative_wetness_pct < 0 ||
        s.relative_wetness_pct > 100
    ) {
        return respond(400, {
            ok: false,
            error: "invalid_soil"
        });
    }

    soilMsg = {
        payload: [
            {
                soil_adc_raw: s.raw,
                soil_adc_filtered: s.filtered_raw,
                relative_wetness_pct: s.relative_wetness_pct
            },
            { ...tags }
        ]
    };
}

// 5. เตรียมข้อมูล AMG8833 Thermal
if (data.thermal !== undefined && data.thermal !== null) {
    const pixels = data.thermal.pixels;

    if (
        !Array.isArray(pixels) ||
        pixels.length !== 64 ||
        !pixels.every(v =>
            validNumber(v) && v >= -40 && v <= 125
        )
    ) {
        return respond(400, {
            ok: false,
            error: "invalid_thermal"
        });
    }

    let leftTotal = 0;
    let rightTotal = 0;

    for (let i = 0; i < 64; i++) {
        if (i % 8 < 4) {
            leftTotal += pixels[i];
        } else {
            rightTotal += pixels[i];
        }
    }

    const left = leftTotal / 32;
    const right = rightTotal / 32;

    thermalMsg = {
        payload: [
            {
                t_left_c: left,
                t_right_c: right,
                t_min_c: Math.min(...pixels),
                t_max_c: Math.max(...pixels),
                delta_t_c: Math.abs(left - right)
            },
            { ...tags }
        ]
    };
}

// 6. ต้องมีข้อมูลเซนเซอร์อย่างน้อยหนึ่งชนิด
if (!soilMsg && !thermalMsg) {
    return respond(400, {
        ok: false,
        error: "no_sensor_data"
    });
}

// 202 หมายถึงรับข้อมูลเพื่อส่งต่อให้ InfluxDB
// ยังไม่ใช่การยืนยันว่า Database เขียนสำเร็จ
return respond(202, {
    ok: true,
    accepted: true,
    soil: soilMsg !== null,
    thermal: thermalMsg !== null
}, soilMsg, thermalMsg);

msg.payload = [
    {
        t_left_c: 27.3,
        t_right_c: 28.6,
        t_max_c: 29.7,
        delta_t_c: 1.3
    },
    {
        plant_id: "plant01",
        device_id: "esp32_01",
        data_source: "simulated"
    }
];

return msg;

msg.payload = [
    {
        soil_adc_raw: 2514,
        soil_adc_filtered: 2514,
        relative_wetness_pct: 29.4
    },
    {
        plant_id: "plant01",
        device_id: "esp32_01",
        data_source: "simulated"
    }
];

return msg;
